    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();
    let dynamic_horizon = (step_index as f64 / total_jobs as f64) * 2.0;
    let lookahead_cpu = next_job_cpu as f64 / node_capacity_cpu as f64;
    let lookahead_ram = next_job_ram as f64 / node_capacity_ram as f64;

    let mut score = cpu_norm + ram_norm - imbalance_penalty + dynamic_horizon;

    if job_cpu > job_ram {
        score += (1.0 - cpu_norm) * 2.0;
        score -= lookahead_cpu * 3.0;
    } else if job_ram > job_cpu {
        score += (1.0 - ram_norm) * 2.0;
        score -= lookahead_ram * 3.0;
    }

    if step_index < total_jobs / 4 {
        score += (1.0 - cpu_norm).powi(2);
        score += (1.0 - ram_norm).powi(2);
    } else if step_index > total_jobs * 3 / 4 {
