    let bin_residual_space = (node_residual_cpu as f64 / node_capacity_cpu as f64).min(1.0);
    let dead_space_ratio = 1.0 - (bin_residual_space + ram_norm * (1.0 - bin_residual_space)).clamp(0.0, 1.0);
    score -= dead_space_ratio * 0.5;

    // Lookahead packing bonuses
    if next_job_cpu + job_cpu <= node_capacity_cpu && next_job_ram + job_ram <= node_capacity_ram {
        score += (lookahead_cpu + lookahead_ram) * 2.0;
    }

    let score = score * 0.95 + ((node_residual_cpu as f64 / node_capacity_cpu as f64) as f64) * 0.05;
    score
}

